// Daftar brand harus SAMA dengan nilai "q" di tiap node Serper
const brands = ['Tokopedia', 'Shopee', 'Lazada'];

// Nama node harus SAMA PERSIS dengan nama di canvas
const nodeNames = [
  'Serper - Brand Utama',
  'Serper - Kompetitor 1',
  'Serper - Kompetitor 2'
];

const results = brands.map((brand, i) => {
  const news = $(nodeNames[i]).first().json.news || [];

  // Mention = berita yang judul/snippet-nya menyebut nama brand
  const relevant = news.filter(n =>
     (n.title || '').toLowerCase().includes(brand.toLowerCase())
   );

  return {
    brand,
    totalFetched: news.length,
    mentions: relevant.length,
    texts: relevant.map(n => `- ${n.title}. ${n.snippet}`).join('\n'),
    headlines: relevant.slice(0, 5).map(n => ({
      title: n.title,
      source: n.source,
      link: n.link,
      date: n.date
    }))
  };
});

const total = results.reduce((sum, r) => sum + r.mentions, 0);

results.forEach(r => {
  r.sov = total > 0 ? Number(((r.mentions / total) * 100).toFixed(1)) : 0;
});

return [{ json: { results, totalMentions: total } }];

// Data SoV dari node "Hitung SoV"
const sov = $('Hitung SoV').first().json.results;

// Ambil teks balasan AI (nama field bisa "text" atau "output")
let raw = $input.first().json.text || $input.first().json.output || '';

// Ambil hanya bagian JSON dari "{" pertama sampai "}" terakhir
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
raw = raw.substring(start, end + 1);
const ai = JSON.parse(raw);

const tanggal = new Date().toLocaleDateString('id-ID', { dateStyle: 'long' });

// Hilangkan tanda bintang markdown dari ringkasan
const ringkasan = (ai.executive_summary || '').replace(/\*/g, '');

const rows = sov.map(r => {
  const a = ai.brands.find(b => b.brand.toLowerCase() === r.brand.toLowerCase()) || {};
  return `<tr>
    <td><b>${r.brand}</b></td>
    <td>${r.mentions}</td>
    <td>${r.sov}%</td>
    <td>${a.sentiment || '-'}</td>
    <td>${a.reputation_score || '-'}/10</td>
    <td>${a.reason || '-'}</td>
  </tr>`;
}).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8">
<style>
  body{font-family:Arial,sans-serif;margin:40px;color:#222}
  h1{color:#1a3c6e;border-bottom:3px solid #1a3c6e;padding-bottom:8px}
  h2{color:#1a3c6e;margin-top:30px}
  table{width:100%;border-collapse:collapse;margin-top:12px;font-size:13px}
  th{background:#1a3c6e;color:#fff;padding:10px;text-align:left}
  td{border:1px solid #ccc;padding:10px;vertical-align:top}
  tr:nth-child(even){background:#f3f6fb}
  .box{background:#eef3fa;padding:16px;border-left:5px solid #1a3c6e;line-height:1.6}
  .foot{margin-top:30px;font-size:11px;color:#777}
</style></head><body>
<h1>Laporan Competitor Monitoring</h1>
<p>Tanggal: ${tanggal} | Periode berita: 1 minggu terakhir</p>
<h2>Ringkasan Eksekutif</h2>
<div class="box">${ringkasan}</div>
<h2>Tabel Perbandingan</h2>
<table>
  <tr><th>Brand</th><th>Mention</th><th>Share of Voice</th><th>Sentimen</th><th>Skor Reputasi</th><th>Alasan</th></tr>
  ${rows}
</table>
<p class="foot">Dibuat otomatis dengan n8n, Serper API, dan AI.</p>
</body></html>`;

return [{ json: { html } }];
